tasks.solution:
from bs4 import BeautifulSoup

soup = BeautifulSoup(html_text, "html.parser")
prices = {}
for row in soup.select("#prices tr")[1:]:
    item, price = [td.get_text(strip=True) for td in row.find_all("td")]
    prices[item] = float(price.lstrip("£"))
